	private static readonly Dictionary<string, UnityPackageAssemblyInfo> s_map = new();
	private static readonly Dictionary<(string assemblyName, string @namespace, string className), UnityGuid> s_scriptGuidMap = new();

	static UnityPackageAssemblyMap()
	{
		using StringReader reader = new(Data);
		string? line;
		while ((line = reader.ReadLine()) is not null)
		{
			if (line.Length == 0)
			{
				continue;
			}
			string[] parts = line.Split('|');
			if (parts[0] == "A" && parts.Length == 5)
			{
				s_map[parts[1]] = new UnityPackageAssemblyInfo(parts[2], UnityGuid.Parse(parts[3]), parts[4]);
			}
			else if (parts[0] == "S" && parts.Length == 5)
			{
				s_scriptGuidMap[(parts[1], parts[2], parts[3])] = UnityGuid.Parse(parts[4]);
			}
		}
	}

	public static bool TryGetInfo(string assemblyName, out UnityPackageAssemblyInfo info)
		=> s_map.TryGetValue(assemblyName, out info);

	public static bool TryGetScriptGuid(string assemblyName, string @namespace, string className, out UnityGuid guid)
		=> s_scriptGuidMap.TryGetValue((assemblyName, @namespace, className), out guid);
}
